code='''from collections import deque
def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        col=grid[r][c]
        if col==6 or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); cells=[]
        while q:
          y,x=q.pop(); cells.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b=y+dy,x+dx
            if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==col:
              seen.add((a,b)); q.append((a,b))
        comps.append((col,cells))
    def sig(cells):
      mn=min(y for y,x in cells); xn=min(x for y,x in cells)
      return frozenset((y-mn,x-xn) for y,x in cells)
    # recolor smaller component when its exact shape is also present in a different color
    for i,(col,cells) in enumerate(comps):
      s=sig(cells)
      for other,ocells in comps:
        if other!=col and sig(ocells)==s:
          for y,x in cells: out[y][x]=other
          break
    return out
'''
